@pytest.mark.asyncio
async def test_redis_publish_on_broadcast(server_args, redis_env, db_tmpfile):
    host, port = server_args["host"], server_args["port"]
    task = await _run_server(host, port)
    try:
        url = f"ws://{host}:{port}"
        async with websockets.connect(url) as ws:
            await ws.recv()
            await ws.send(json.dumps({
                "type": "broadcast",
                "payload": {"text": "redistest"},
            }))
            await asyncio.wait_for(ws.recv(), timeout=5)

        await asyncio.sleep(0.3)
        r = await server._get_redis()
        assert r is not None
        pubsub = r.pubsub()
        await pubsub.subscribe("broadcast")
        msg = await asyncio.wait_for(pubsub.get_message(ignore_subscribe_messages=True, timeout=5), timeout=5)
        while msg:
            try:
                envelope = json.loads(msg["data"])
                data = json.loads(envelope["data"])
                if data.get("payload") == {"text": "redistest"}:
                    assert envelope["source"] == server.SERVER_ID
                    break
            except (json.JSONDecodeError, KeyError):
                pass
            try:
                msg = await asyncio.wait_for(pubsub.get_message(ignore_subscribe_messages=True, timeout=0.3), timeout=0.3)
            except asyncio.TimeoutError:
                msg = None
        else:
            assert False, "Broadcast message not found in Redis"
    finally:
        await _stop_server(task)

